import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

public class StartAutoLoadPolicyTests {

    private SyncedEnforcer syncedEnforcer;
    private AtomicInteger autoLoadRunning;

    @Before
    public void setUp() {
        syncedEnforcer = Mockito.spy(new SyncedEnforcer());
        autoLoadRunning = new AtomicInteger(0);
        // Assuming autoLoadRunning is a field in SyncedEnforcer
        // Use reflection to set the private field for testing
        try {
            java.lang.reflect.Field field = SyncedEnforcer.class.getDeclaredField("autoLoadRunning");
            field.setAccessible(true);
            field.set(syncedEnforcer, autoLoadRunning);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    @Test
    public void test_startAutoLoadPolicy_startsNewThread() throws InterruptedException {
        long interval = 1000L;

        syncedEnforcer.startAutoLoadPolicy(interval);

        // Wait a bit to ensure the thread has started
        Thread.sleep(500);

        // Verify that the autoLoadRunning is set to 1
        assertEquals(1, autoLoadRunning.get());

        // Verify that loadPolicy is called at least once
        verify(syncedEnforcer, atLeastOnce()).loadPolicy();

        // Clean up: stop the auto-loading thread
        autoLoadRunning.set(0);
    }

    @Test
    public void test_startAutoLoadPolicy_doesNotStartNewThreadIfAlreadyRunning() {
        long interval = 1000L;

        // Set autoLoadRunning to 1 to simulate an already running process
        autoLoadRunning.set(1);

        syncedEnforcer.startAutoLoadPolicy(interval);

        // Verify that loadPolicy is never called because the process is already running
        verify(syncedEnforcer, never()).loadPolicy();

        // Verify that autoLoadRunning remains 1
        assertEquals(1, autoLoadRunning.get());
    }

    @Test
    public void test_startAutoLoadPolicy_resetsAutoLoadRunningOnInterruption() throws InterruptedException {
        long interval = 1000L;

        syncedEnforcer.startAutoLoadPolicy(interval);

        // Wait a bit to ensure the thread has started
        Thread.sleep(500);

        // Simulate interruption
        autoLoadRunning.set(0);

        // Wait a bit to ensure the thread has stopped
        Thread.sleep(500);

        // Verify that autoLoadRunning is reset to 0
        assertEquals(0, autoLoadRunning.get());
    }
}

